//! A physical quantity (weights, energies, amounts of goods) backed by an
//! exact `BigDecimal`.
//!
//! The mechanical newtype surface (conversions, parsing, arithmetic bridges,
//! serde/sqlx wrapping, primitives) is generated by [`decimal_newtype!`];
//! only `Amount`-specific semantics live here.
//!
//! Serialization is deliberately **string-based** (`"1.250"`): quantities are
//! exact decimals and must survive a REST round-trip without float drift.

use bigdecimal::{BigDecimal, FromPrimitive};
use std::convert::TryFrom;

use super::decimal::decimal_newtype;

decimal_newtype!(
    /// A physical quantity (kg, kJ, pieces…) backed by an exact BigDecimal.
    Amount,
    self_ops {
        // `Div` panics on a zero divisor (BigDecimal semantics). For
        // user-influenced quantities prefer `checked_div` and validate at
        // the call site.
        Add::add,
        Sub::sub,
        Mul::mul,
        Div::div,
    }
);

impl TryFrom<f32> for Amount {
    type Error = &'static str;
    fn try_from(value: f32) -> Result<Self, Self::Error> {
        let decimal = BigDecimal::from_f32(value).ok_or("cannot convert float to decimal")?;
        Ok(Amount(decimal))
    }
}

impl Amount {
    /// Checked division: `None` for a zero divisor instead of a BigDecimal panic.
    pub fn checked_div(&self, rhs: &Amount) -> Option<Amount> {
        if rhs.is_zero() {
            return None;
        }
        // The `&Amount / &Amount` operator impl covers the arithmetic.
        Some(self / rhs)
    }
}
